const productos = $input.all().map(i => i.json);
if (!Array.isArray(productos) || productos.length === 0) throw new Error('WC no devolvió productos');
const base = $env.WOO_BASE_URL + '/wp-json/wc/v3';
const authQS = 'consumer_key=' + $env.WOO_CONSUMER_KEY + '&consumer_secret=' + $env.WOO_CONSUMER_SECRET;

const fichas = [];

for (const p of productos) {
  let variaciones = [];

  if (Array.isArray(p.variations) && p.variations.length > 0) {
    try {
      const vars = await this.helpers.httpRequest({
        method: 'GET',
        url: base + '/products/' + p.id + '/variations?per_page=100&' + authQS
      });
      variaciones = (Array.isArray(vars) ? vars : []).map(v => ({
        variation_id: v.id,
        talla: (v.attributes || []).find(a => ['talla','size'].includes((a.name||'').toLowerCase()))?.option || null,
        color: (v.attributes || []).find(a => a.name?.toLowerCase() === 'color')?.option || null,
        stock: v.stock_quantity,
        sku: v.sku || null,
        precio_cop: v.price || null
      }));
    } catch(e) { /* continua sin variaciones */ }
  }

  const lineas = ['Terra','Natura','Esencia','Equilibrio'];
  const linea = (p.tags || []).find(t => lineas.some(l => t.name?.toLowerCase() === l.toLowerCase()))?.name || null;

  const catMap = {'top':'Tops','legging':'Leggings','set':'Sets'};
  let categoria = null;
  for (const cat of (p.categories || [])) {
    for (const [k,v] of Object.entries(catMap)) {
      if (cat.name?.toLowerCase().includes(k)) { categoria = v; break; }
    }
    if (categoria) break;
  }

  const attrTalla = (p.attributes || []).find(a => ['talla','size'].includes((a.name||'').toLowerCase()));

  fichas.push({
    woo_product_id: p.id,
    nombre: p.name,
    slug: p.slug,
    linea,
    categoria,
    descripcion_corta: (p.short_description || '').replace(/<[^>]+>/g,'').trim().substring(0,500),
    tallas_disponibles: JSON.stringify(attrTalla?.options || []),
    precio_cop: parseFloat(p.price) || 0,
    stock_total: p.stock_quantity || 0,
    url_imagen: p.images?.[0]?.src || null,
    url_producto: p.permalink,
    variaciones: JSON.stringify(variaciones),
    en_oferta: p.on_sale === true,
    precio_regular: parseFloat(p.regular_price) || 0,
    precio_oferta: p.on_sale === true ? (parseFloat(p.sale_price) || parseFloat(p.price) || 0) : 0,
    oferta_hasta: p.date_on_sale_to || ''
  });
}

return fichas.map(f => ({ json: f }));

const items = $input.all();
const total = items.length;
const conStock = items.filter(i => i.json.stock_total > 0).length;
console.log(`Sync completado: ${total} productos, ${conStock} con stock`);
return [{ json: { total_productos: total, con_stock: conStock, ts: new Date().toISOString() } }];

